insert into public.app_config (key, value)
insert into public.verses (no, track, day_no, frame_art, ref, ref_short, ref_full, text, week, is_active)
values
  (1001, 'psalm', 1, 1, '시 1:1', '시 1:1', '시편 1편 1절', '복 있는 사람은 악인들의 꾀를 따르지 아니하며 죄인들의 길에 서지 아니하며 오만한 자들의 자리에 앉지 아니하고', null, false),
  (1002, 'psalm', 2, 2, '시 1:2', '시 1:2', '시편 1편 2절', '오직 여호와의 율법을 즐거워하여 그의 율법을 주야로 묵상하는도다', null, false),
  (1003, 'psalm', 3, 3, '시 1:3', '시 1:3', '시편 1편 3절', '그는 시냇가에 심은 나무가 철을 따라 열매를 맺으며 그 잎사귀가 마르지 아니함 같으니 그가 하는 모든 일이 다 형통하리로다', null, false),
  (1004, 'psalm', 4, 4, '시 3:3', '시 3:3', '시편 3편 3절', '여호와여 주는 나의 방패시요 나의 영광이시요 나의 머리를 드시는 자이시니이다', null, false),
  (1005, 'psalm', 5, 5, '시 3:6', '시 3:6', '시편 3편 6절', '천만인이 나를 에워싸 진 친다 하여도 나는 두려워하지 아니하리이다', null, false),
  (1006, 'psalm', 6, 6, '시 4:7', '시 4:7', '시편 4편 7절', '주께서 내 마음에 두신 기쁨은 그들의 곡식과 새 포도주가 풍성할 때보다 더하니이다', null, false),
  (1007, 'psalm', 7, 7, '시 5:12', '시 5:12', '시편 5편 12절', '여호와여 주는 의인에게 복을 주시고 방패로 함 같이 은혜로 그를 호위하시리이다', null, false),
  (1008, 'psalm', 8, 8, '시 7:17', '시 7:17', '시편 7편 17절', '내가 여호와께 그의 의를 따라 감사함이여 지존하신 여호와의 이름을 찬양하리로다', null, false),
  (1009, 'psalm', 9, 9, '시 8:1', '시 8:1', '시편 8편 1절', '여호와 우리 주여 주의 이름이 온 땅에 어찌 그리 아름다운지요 주의 영광이 하늘을 덮었나이다', null, false),
  (1010, 'psalm', 10, 10, '시 11:7', '시 11:7', '시편 11편 7절', '여호와는 의로우사 의로운 일을 좋아하시나니 정직한 자는 그의 얼굴을 뵈오리로다', null, false),
  (1011, 'psalm', 11, 11, '시 6:9', '시 6:9', '시편 6편 9절', '여호와께서 내 간구를 들으셨음이여 여호와께서 내 기도를 받으시리로다', null, false),
  (1012, 'psalm', 12, 12, '시 8:4', '시 8:4', '시편 8편 4절', '사람이 무엇이기에 주께서 그를 생각하시며 인자가 무엇이기에 주께서 그를 돌보시나이까', null, false),
  (1013, 'psalm', 13, 1, '시 9:9', '시 9:9', '시편 9편 9절', '여호와는 압제를 당하는 자의 요새이시요 환난 때의 요새이시로다', null, false),
  (1014, 'psalm', 14, 2, '시 13:5', '시 13:5', '시편 13편 5절', '나는 오직 주의 사랑을 의지하였사오니 나의 마음은 주의 구원을 기뻐하리이다', null, false),
  (1015, 'psalm', 15, 3, '시 16:8', '시 16:8', '시편 16편 8절', '내가 여호와를 항상 내 앞에 모심이여 그가 나의 오른쪽에 계시므로 내가 흔들리지 아니하리로다', null, false),
  (1016, 'psalm', 16, 4, '시 16:11', '시 16:11', '시편 16편 11절', '주께서 생명의 길을 내게 보이시리니 주의 앞에는 충만한 기쁨이 있고 주의 오른쪽에는 영원한 즐거움이 있나이다', null, false),
  (1017, 'psalm', 17, 5, '시 18:1', '시 18:1', '시편 18편 1절', '나의 힘이신 여호와여 내가 주를 사랑하나이다', null, false),
  (1018, 'psalm', 18, 6, '시 19:1', '시 19:1', '시편 19편 1절', '하늘이 하나님의 영광을 선포하고 궁창이 그의 손으로 하신 일을 나타내는도다', null, false),
  (1019, 'psalm', 19, 7, '시 19:14', '시 19:14', '시편 19편 14절', '나의 반석이시요 나의 구속자이신 여호와여 내 입의 말과 마음의 묵상이 주님 앞에 열납되기를 원하나이다', null, false),
  (1020, 'psalm', 20, 8, '시 20:7', '시 20:7', '시편 20편 7절', '어떤 사람은 병거, 어떤 사람은 말을 의지하나 우리는 여호와 우리 하나님의 이름을 자랑하리로다', null, false),
  (1021, 'psalm', 21, 9, '시 22:1', '시 22:1', '시편 22편 1절', '내 하나님이여 내 하나님이여 어찌 나를 버리셨나이까 어찌 나를 멀리 하여 돕지 아니하시오며 내 신음 소리를 듣지 아니하시나이까', null, false),
  (1022, 'psalm', 22, 10, '시 23:1', '시 23:1', '시편 23편 1절', '여호와는 나의 목자시니 내게 부족함이 없으리로다', null, false),
  (1023, 'psalm', 23, 11, '시 23:2', '시 23:2', '시편 23편 2절', '그가 나를 푸른 풀밭에 누이시며 쉴 만한 물 가로 인도하시는도다', null, false),
  (1024, 'psalm', 24, 12, '시 23:3', '시 23:3', '시편 23편 3절', '내 영혼을 소생시키시고 자기 이름을 위하여 의의 길로 인도하시는도다', null, false),
  (1025, 'psalm', 25, 1, '시 23:4', '시 23:4', '시편 23편 4절', '내가 사망의 음침한 골짜기로 다닐지라도 해를 두려워하지 않을 것은 주께서 나와 함께 하심이라 주의 지팡이와 막대기가 나를 안위하시나이다', null, false),
  (1026, 'psalm', 26, 2, '시 23:5', '시 23:5', '시편 23편 5절', '주께서 내 원수의 목전에서 내게 상을 차려 주시고 기름을 내 머리에 부으셨으니 내 잔이 넘치나이다', null, false),
  (1027, 'psalm', 27, 3, '시 23:6', '시 23:6', '시편 23편 6절', '내 평생에 선하심과 인자하심이 반드시 나를 따르리니 내가 여호와의 집에 영원히 살리로다', null, false),
  (1028, 'psalm', 28, 4, '시 24:1', '시 24:1', '시편 24편 1절', '땅과 거기에 충만한 것과 세계와 그 가운데에 사는 자들은 다 여호와의 것이로다', null, false),
  (1029, 'psalm', 29, 5, '시 25:4', '시 25:4', '시편 25편 4절', '여호와여 주의 도를 내게 보이시고 주의 길을 내게 가르치소서', null, false),
  (1030, 'psalm', 30, 6, '시 25:5', '시 25:5', '시편 25편 5절', '주의 진리로 나를 지도하시고 교훈하소서 주는 내 구원의 하나님이시니 내가 종일 주를 기다리나이다', null, false),
  (1031, 'psalm', 31, 7, '시 27:1', '시 27:1', '시편 27편 1절', '여호와는 나의 빛이요 나의 구원이시니 내가 누구를 두려워하리요 여호와는 내 생명의 능력이시니 내가 누구를 무서워하리요', null, false),
  (1032, 'psalm', 32, 8, '시 27:14', '시 27:14', '시편 27편 14절', '너는 여호와를 기다릴지어다 강하고 담대하며 여호와를 기다릴지어다', null, false),
  (1033, 'psalm', 33, 9, '시 30:5', '시 30:5', '시편 30편 5절', '그의 노염은 잠깐이요 그의 은총은 평생이로다 저녁에는 울음이 깃들일지라도 아침에는 기쁨이 오리로다', null, false),
  (1034, 'psalm', 34, 10, '시 31:3', '시 31:3', '시편 31편 3절', '주는 나의 반석과 산성이시니 그러므로 주의 이름을 생각하셔서 나를 인도하시고 지도하소서', null, false),
  (1035, 'psalm', 35, 11, '시 32:8', '시 32:8', '시편 32편 8절', '내가 네 갈 길을 가르쳐 보이고 너를 주목하여 훈계하리로다', null, false),
  (1036, 'psalm', 36, 12, '시 33:12', '시 33:12', '시편 33편 12절', '여호와를 자기 하나님으로 삼은 나라 곧 하나님의 기업으로 선택된 백성은 복이 있도다', null, false),
  (1037, 'psalm', 37, 1, '시 34:1', '시 34:1', '시편 34편 1절', '내가 여호와를 항상 송축함이여 내 입술로 항상 주를 찬양하리이다', null, false),
  (1038, 'psalm', 38, 2, '시 34:8', '시 34:8', '시편 34편 8절', '너희는 여호와의 선하심을 맛보아 알지어다 그에게 피하는 자는 복이 있도다', null, false),
  (1039, 'psalm', 39, 3, '시 34:18', '시 34:18', '시편 34편 18절', '여호와는 마음이 상한 자를 가까이 하시고 충심으로 통회하는 자를 구원하시는도다', null, false),
  (1040, 'psalm', 40, 4, '시 34:19', '시 34:19', '시편 34편 19절', '의인은 고난이 많으나 여호와께서 그의 모든 고난에서 건지시는도다', null, false),
  (1041, 'psalm', 41, 5, '시 37:3', '시 37:3', '시편 37편 3절', '여호와를 의뢰하고 선을 행하라 땅에 머무는 동안 그의 성실을 먹을 거리로 삼을지어다', null, false),
  (1042, 'psalm', 42, 6, '시 37:4', '시 37:4', '시편 37편 4절', '또 여호와를 기뻐하라 그가 네 마음의 소원을 네게 이루어 주시리로다', null, false),
  (1043, 'psalm', 43, 7, '시 37:5', '시 37:5', '시편 37편 5절', '네 길을 여호와께 맡기라 그를 의지하면 그가 이루시고', null, false),
  (1044, 'psalm', 44, 8, '시 40:1', '시 40:1', '시편 40편 1절', '내가 여호와를 기다리고 기다렸더니 귀를 기울이사 나의 부르짖음을 들으셨도다', null, false),
  (1045, 'psalm', 45, 9, '시 42:1', '시 42:1', '시편 42편 1절', '하나님이여 사슴이 시냇물을 찾기에 갈급함 같이 내 영혼이 주를 찾기에 갈급하니이다', null, false),
  (1046, 'psalm', 46, 10, '시 46:1', '시 46:1', '시편 46편 1절', '하나님은 우리의 피난처시요 힘이시니 환난 중에 만날 큰 도움이시라', null, false),
  (1047, 'psalm', 47, 11, '시 51:10', '시 51:10', '시편 51편 10절', '하나님이여 내 속에 정한 마음을 창조하시고 내 안에 정직한 영을 새롭게 하소서', null, false),
  (1048, 'psalm', 48, 12, '시 51:17', '시 51:17', '시편 51편 17절', '하나님께서 구하시는 제사는 상한 심령이라 하나님이여 상하고 통회하는 마음을 주께서 멸시하지 아니하시리이다', null, false),
  (1049, 'psalm', 49, 1, '시 55:22', '시 55:22', '시편 55편 22절', '네 짐을 여호와께 맡기라 그가 너를 붙드시고 의인의 요동함을 영원히 허락하지 아니하시리로다', null, false),
  (1050, 'psalm', 50, 2, '시 56:3', '시 56:3', '시편 56편 3절', '내가 두려워하는 날에는 내가 주를 의지하리이다', null, false),
  (1051, 'psalm', 51, 3, '시 61:2', '시 61:2', '시편 61편 2절', '내 마음이 약해 질 때에 땅 끝에서부터 주께 부르짖으오리니 나보다 높은 바위에 나를 인도하소서', null, false),
  (1052, 'psalm', 52, 4, '시 62:1', '시 62:1', '시편 62편 1절', '나의 영혼이 잠잠히 하나님만 바람이여 나의 구원이 그에게서 나오는도다', null, false),
  (1053, 'psalm', 53, 5, '시 66:18', '시 66:18', '시편 66편 18절', '내가 나의 마음에 죄악을 품었더라면 주께서 듣지 아니하시리라', null, false),
  (1054, 'psalm', 54, 6, '시 73:26', '시 73:26', '시편 73편 26절', '내 육체와 마음은 쇠약하나 하나님은 내 마음의 반석이시요 영원한 분깃이시라', null, false),
  (1055, 'psalm', 55, 7, '시 84:10', '시 84:10', '시편 84편 10절', '주의 궁정에서의 한 날이 다른 곳에서의 천 날보다 나은즉 악인의 장막에 사는 것보다 내 하나님의 성전 문지기로 있는 것이 좋사오니', null, false),
  (1056, 'psalm', 56, 8, '시 84:11', '시 84:11', '시편 84편 11절', '여호와 하나님은 해요 방패이시라 여호와께서 은혜와 영화를 주시며 정직하게 행하는 자에게 좋은 것을 아끼지 아니하실 것임이니이다', null, false),
  (1057, 'psalm', 57, 9, '시 86:5', '시 86:5', '시편 86편 5절', '주는 선하사 사죄하기를 즐거워하시며 주께 부르짖는 자에게 인자함이 후하심이니이다', null, false),
  (1058, 'psalm', 58, 10, '시 86:11', '시 86:11', '시편 86편 11절', '여호와여 주의 도를 내게 가르치소서 내가 주의 진리에 행하오리니 일심으로 주의 이름을 경외하게 하소서', null, false),
  (1059, 'psalm', 59, 11, '시 90:12', '시 90:12', '시편 90편 12절', '우리에게 우리 날 계수함을 가르치사 지혜로운 마음을 얻게 하소서', null, false),
  (1060, 'psalm', 60, 12, '시 91:1', '시 91:1', '시편 91편 1절', '지존자의 은밀한 곳에 거주하며 전능자의 그늘 아래에 사는 자여,', null, false),
  (1061, 'psalm', 61, 1, '시 91:2', '시 91:2', '시편 91편 2절', '나는 여호와를 향하여 말하기를 그는 나의 피난처요 나의 요새요 내가 의뢰하는 하나님이라 하리니', null, false),
  (1062, 'psalm', 62, 2, '시 91:11', '시 91:11', '시편 91편 11절', '그가 너를 위하여 그의 천사들을 명령하사 네 모든 길에서 너를 지키게 하심이라', null, false),
  (1063, 'psalm', 63, 3, '시 95:1', '시 95:1', '시편 95편 1절', '오라 우리가 여호와께 노래하며 우리의 구원의 반석을 향하여 즐거이 외치자', null, false),
  (1064, 'psalm', 64, 4, '시 95:6', '시 95:6', '시편 95편 6절', '오라 우리가 굽혀 경배하며 우리를 지으신 여호와 앞에 무릎을 꿇자', null, false),
  (1065, 'psalm', 65, 5, '시 96:1', '시 96:1', '시편 96편 1절', '새 노래로 여호와께 노래하라 온 땅이여 여호와께 노래할지어다', null, false),
  (1066, 'psalm', 66, 6, '시 100:1-2', '시 100:1-2', '시편 100편 1-2절', '온 땅이여 여호와께 즐거운 찬송을 부를지어다 기쁨으로 여호와를 섬기며 노래하면서 그의 앞에 나아갈지어다', null, false),
  (1067, 'psalm', 67, 7, '시 100:5', '시 100:5', '시편 100편 5절', '여호와는 선하시니 그의 인자하심이 영원하고 그의 성실하심이 대대에 이르리로다', null, false),
  (1068, 'psalm', 68, 8, '시 103:1', '시 103:1', '시편 103편 1절', '내 영혼아 여호와를 송축하라 내 속에 있는 것들아 다 그의 거룩한 이름을 송축하라', null, false),
  (1069, 'psalm', 69, 9, '시 103:2', '시 103:2', '시편 103편 2절', '내 영혼아 여호와를 송축하며 그의 모든 은택을 잊지 말지어다', null, false),
  (1070, 'psalm', 70, 10, '시 103:12', '시 103:12', '시편 103편 12절', '동이 서에서 먼 것 같이 우리의 죄과를 우리에게서 멀리 옮기셨으며', null, false),
  (1071, 'psalm', 71, 11, '시 105:4', '시 105:4', '시편 105편 4절', '여호와와 그의 능력을 구할지어다 그의 얼굴을 항상 구할지어다', null, false),
  (1072, 'psalm', 72, 12, '시 107:1', '시 107:1', '시편 107편 1절', '여호와께 감사하라 그는 선하시며 그 인자하심이 영원함이로다', null, false),
  (1073, 'psalm', 73, 1, '시 112:1', '시 112:1', '시편 112편 1절', '할렐루야, 여호와를 경외하며 그의 계명을 크게 즐거워하는 자는 복이 있도다', null, false),
  (1074, 'psalm', 74, 2, '시 116:12', '시 116:12', '시편 116편 12절', '내게 주신 모든 은혜를 내가 여호와께 무엇으로 보답할까', null, false),
  (1075, 'psalm', 75, 3, '시 118:8', '시 118:8', '시편 118편 8절', '여호와께 피하는 것이 사람을 신뢰하는 것보다 나으며', null, false),
  (1076, 'psalm', 76, 4, '시 118:24', '시 118:24', '시편 118편 24절', '이 날은 여호와께서 정하신 것이라 이 날에 우리가 즐거워하고 기뻐하리로다', null, false),
  (1077, 'psalm', 77, 5, '시 119:9', '시 119:9', '시편 119편 9절', '청년이 무엇으로 그의 행실을 깨끗하게 하리이까 주의 말씀만 지킬 따름이니이다', null, false),
  (1078, 'psalm', 78, 6, '시 119:11', '시 119:11', '시편 119편 11절', '내가 주께 범죄하지 아니하려 하여 주의 말씀을 내 마음에 두었나이다', null, false),
  (1079, 'psalm', 79, 7, '시 119:50', '시 119:50', '시편 119편 50절', '이 말씀은 나의 고난 중의 위로라 주의 말씀이 나를 살리셨기 때문이니이다', null, false),
  (1080, 'psalm', 80, 8, '시 119:105', '시 119:105', '시편 119편 105절', '주의 말씀은 내 발에 등이요 내 길에 빛이니이다', null, false),
  (1081, 'psalm', 81, 9, '시 119:130', '시 119:130', '시편 119편 130절', '주의 말씀을 열면 빛이 비치어 우둔한 사람들을 깨닫게 하나이다', null, false),
  (1082, 'psalm', 82, 10, '시 119:165', '시 119:165', '시편 119편 165절', '주의 법을 사랑하는 자에게는 큰 평안이 있으니 그들에게 장애물이 없으리이다', null, false),
  (1083, 'psalm', 83, 11, '시 121:1-2', '시 121:1-2', '시편 121편 1-2절', '내가 산을 향하여 눈을 들리라 나의 도움이 어디서 올까 나의 도움은 천지를 지으신 여호와에게서로다', null, false),
  (1084, 'psalm', 84, 12, '시 121:7', '시 121:7', '시편 121편 7절', '여호와께서 너를 지켜 모든 환난을 면하게 하시며 또 네 영혼을 지키시리로다', null, false),
  (1085, 'psalm', 85, 1, '시 121:8', '시 121:8', '시편 121편 8절', '여호와께서 너의 출입을 지금부터 영원까지 지키시리로다', null, false),
  (1086, 'psalm', 86, 2, '시 122:1', '시 122:1', '시편 122편 1절', '사람이 내게 말하기를 여호와의 집에 올라가자 할 때에 내가 기뻐하였도다', null, false),
  (1087, 'psalm', 87, 3, '시 126:5', '시 126:5', '시편 126편 5절', '눈물을 흘리며 씨를 뿌리는 자는 기쁨으로 거두리로다', null, false),
  (1088, 'psalm', 88, 4, '시 126:6', '시 126:6', '시편 126편 6절', '울며 씨를 뿌리러 나가는 자는 반드시 기쁨으로 그 곡식 단을 가지고 돌아오리로다', null, false),
  (1089, 'psalm', 89, 5, '시 127:1', '시 127:1', '시편 127편 1절', '여호와께서 집을 세우지 아니하시면 세우는 자의 수고가 헛되며 여호와께서 성을 지키지 아니하시면 파수꾼의 깨어 있음이 헛되도다', null, false),
  (1090, 'psalm', 90, 6, '시 130:5', '시 130:5', '시편 130편 5절', '나 곧 내 영혼은 여호와를 기다리며 나는 주의 말씀을 바라는도다', null, false),
  (1091, 'psalm', 91, 7, '시 133:1', '시 133:1', '시편 133편 1절', '보라 형제가 연합하여 동거함이 어찌 그리 선하고 아름다운고', null, false),
  (1092, 'psalm', 92, 8, '시 139:1', '시 139:1', '시편 139편 1절', '여호와여 주께서 나를 살펴 보셨으므로 나를 아시나이다', null, false),
  (1093, 'psalm', 93, 9, '시 139:14', '시 139:14', '시편 139편 14절', '내가 주께 감사하옴은 나를 지으심이 심히 기묘하심이라 주께서 하시는 일이 기이함을 내 영혼이 잘 아나이다', null, false),
  (1094, 'psalm', 94, 10, '시 139:23', '시 139:23', '시편 139편 23절', '하나님이여 나를 살피사 내 마음을 아시며 나를 시험하사 내 뜻을 아옵소서', null, false),
  (1095, 'psalm', 95, 11, '시 139:24', '시 139:24', '시편 139편 24절', '내게 무슨 악한 행위가 있나 보시고 나를 영원한 길로 인도하소서', null, false),
  (1096, 'psalm', 96, 12, '시 145:8', '시 145:8', '시편 145편 8절', '여호와는 은혜로우시며 긍휼이 많으시며 노하기를 더디 하시며 인자하심이 크시도다', null, false),
  (1097, 'psalm', 97, 1, '시 145:9', '시 145:9', '시편 145편 9절', '여호와께서는 모든 것을 선대하시며 그 지으신 모든 것에 긍휼을 베푸시는도다', null, false),
  (1098, 'psalm', 98, 2, '시 145:18', '시 145:18', '시편 145편 18절', '여호와께서는 자기에게 간구하는 모든 자 곧 진실하게 간구하는 모든 자에게 가까이 하시는도다', null, false),
  (1099, 'psalm', 99, 3, '시 146:2', '시 146:2', '시편 146편 2절', '나의 생전에 여호와를 찬양하며 나의 평생에 내 하나님을 찬송하리로다', null, false),
  (1100, 'psalm', 100, 4, '시 147:3', '시 147:3', '시편 147편 3절', '상심한 자들을 고치시며 그들의 상처를 싸매시는도다', null, false),
  (1101, 'psalm', 101, 5, '시 150:6', '시 150:6', '시편 150편 6절', '호흡이 있는 자마다 여호와를 찬양할지어다 할렐루야', null, false),
  (1102, 'psalm', 102, 6, '잠 1:7', '잠 1:7', '잠언 1장 7절', '여호와를 경외하는 것이 지식의 근본이거늘 미련한 자는 지혜와 훈계를 멸시하느니라', null, false),
  (1103, 'psalm', 103, 7, '잠 1:8', '잠 1:8', '잠언 1장 8절', '내 아들아 네 아비의 훈계를 들으며 네 어미의 법을 떠나지 말라', null, false),
  (1104, 'psalm', 104, 8, '잠 2:6', '잠 2:6', '잠언 2장 6절', '대저 여호와는 지혜를 주시며 지식과 명철을 그 입에서 내심이며', null, false),
  (1105, 'psalm', 105, 9, '잠 3:3', '잠 3:3', '잠언 3장 3절', '인자와 진리가 네게서 떠나지 말게 하고 그것을 네 목에 매며 네 마음판에 새기라', null, false),
  (1106, 'psalm', 106, 10, '잠 3:5-6', '잠 3:5-6', '잠언 3장 5-6절', '너는 마음을 다하여 여호와를 신뢰하고 네 명철을 의지하지 말라 너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라', null, false),
  (1107, 'psalm', 107, 11, '잠 3:7', '잠 3:7', '잠언 3장 7절', '스스로 지혜롭게 여기지 말지어다 여호와를 경외하며 악을 떠날지어다', null, false),
  (1108, 'psalm', 108, 12, '잠 3:9', '잠 3:9', '잠언 3장 9절', '네 재물과 네 소산물의 처음 익은 열매로 여호와를 공경하라', null, false),
  (1109, 'psalm', 109, 1, '잠 3:11', '잠 3:11', '잠언 3장 11절', '내 아들아 여호와의 징계를 경히 여기지 말라 그 꾸지람을 싫어하지 말라', null, false),
  (1110, 'psalm', 110, 2, '잠 3:12', '잠 3:12', '잠언 3장 12절', '대저 여호와께서 그 사랑하시는 자를 징계하시기를 마치 아비가 그 기뻐하는 아들을 징계함 같이 하시느니라', null, false),
  (1111, 'psalm', 111, 3, '잠 3:27', '잠 3:27', '잠언 3장 27절', '네 손이 선을 베풀 힘이 있거든 마땅히 받을 자에게 베풀기를 아끼지 말며', null, false),
  (1112, 'psalm', 112, 4, '잠 4:7', '잠 4:7', '잠언 4장 7절', '지혜가 제일이니 지혜를 얻으라 네가 얻은 모든 것을 가지고 명철을 얻을지니라', null, false),
  (1113, 'psalm', 113, 5, '잠 4:18', '잠 4:18', '잠언 4장 18절', '의인의 길은 돋는 햇살 같아서 크게 빛나 한낮의 광명에 이르거니와', null, false),
  (1114, 'psalm', 114, 6, '잠 4:23', '잠 4:23', '잠언 4장 23절', '모든 지킬 만한 것 중에 더욱 네 마음을 지키라 생명의 근원이 이에서 남이니라', null, false),
  (1115, 'psalm', 115, 7, '잠 6:6', '잠 6:6', '잠언 6장 6절', '게으른 자여 개미에게 가서 그가 하는 것을 보고 지혜를 얻으라', null, false),
  (1116, 'psalm', 116, 8, '잠 8:17', '잠 8:17', '잠언 8장 17절', '나를 사랑하는 자들이 나의 사랑을 입으며 나를 간절히 찾는 자가 나를 만날 것이니라', null, false),
  (1117, 'psalm', 117, 9, '잠 9:10', '잠 9:10', '잠언 9장 10절', '여호와를 경외하는 것이 지혜의 근본이요 거룩하신 자를 아는 것이 명철이니라', null, false),
  (1118, 'psalm', 118, 10, '잠 10:12', '잠 10:12', '잠언 10장 12절', '미움은 다툼을 일으켜도 사랑은 모든 허물을 가리느니라', null, false),
  (1119, 'psalm', 119, 11, '잠 10:19', '잠 10:19', '잠언 10장 19절', '말이 많으면 허물을 면하기 어려우나 그 입술을 제어하는 자는 지혜가 있느니라', null, false),
  (1120, 'psalm', 120, 12, '잠 10:22', '잠 10:22', '잠언 10장 22절', '여호와께서 주시는 복은 사람을 부하게 하고 근심을 겸하여 주지 아니하시느니라', null, false),
  (1121, 'psalm', 121, 1, '잠 11:2', '잠 11:2', '잠언 11장 2절', '교만이 오면 욕도 오거니와 겸손한 자에게는 지혜가 있느니라', null, false),
  (1122, 'psalm', 122, 2, '잠 11:24', '잠 11:24', '잠언 11장 24절', '흩어 구제하여도 더욱 부하게 되는 일이 있나니 과도히 아껴도 가난하게 될 뿐이니라', null, false),
  (1123, 'psalm', 123, 3, '잠 11:25', '잠 11:25', '잠언 11장 25절', '구제를 좋아하는 자는 풍족하여질 것이요 남을 윤택하게 하는 자는 자기도 윤택하여지리라', null, false),
  (1124, 'psalm', 124, 4, '잠 12:15', '잠 12:15', '잠언 12장 15절', '미련한 자는 자기 행위를 바른 줄로 여기나 지혜로운 자는 권고를 듣느니라', null, false),
  (1125, 'psalm', 125, 5, '잠 12:25', '잠 12:25', '잠언 12장 25절', '근심이 사람의 마음에 있으면 그것으로 번뇌하게 되나 선한 말은 그것을 즐겁게 하느니라', null, false),
  (1126, 'psalm', 126, 6, '잠 13:3', '잠 13:3', '잠언 13장 3절', '입을 지키는 자는 자기의 생명을 보전하나 입술을 크게 벌리는 자에게는 멸망이 오느니라', null, false),
  (1127, 'psalm', 127, 7, '잠 13:20', '잠 13:20', '잠언 13장 20절', '지혜로운 자와 동행하면 지혜를 얻고 미련한 자와 사귀면 해를 받느니라', null, false),
  (1128, 'psalm', 128, 8, '잠 14:12', '잠 14:12', '잠언 14장 12절', '어떤 길은 사람이 보기에 바르나 필경은 사망의 길이니라', null, false),
  (1129, 'psalm', 129, 9, '잠 14:26', '잠 14:26', '잠언 14장 26절', '여호와를 경외하는 자에게는 견고한 의뢰가 있나니 그 자녀들에게 피난처가 있으리라', null, false),
  (1130, 'psalm', 130, 10, '잠 14:34', '잠 14:34', '잠언 14장 34절', '공의는 나라를 영화롭게 하고 죄는 백성을 욕되게 하느니라', null, false),
  (1131, 'psalm', 131, 11, '잠 15:1', '잠 15:1', '잠언 15장 1절', '유순한 대답은 분노를 쉬게 하여도 과격한 말은 노를 격동하느니라', null, false),
  (1132, 'psalm', 132, 12, '잠 15:3', '잠 15:3', '잠언 15장 3절', '여호와의 눈은 어디서든지 악인과 선인을 감찰하시느니라', null, false),
  (1133, 'psalm', 133, 1, '잠 15:13', '잠 15:13', '잠언 15장 13절', '마음의 즐거움은 얼굴을 빛나게 하여도 마음의 근심은 심령을 상하게 하느니라', null, false),
  (1134, 'psalm', 134, 2, '잠 15:16', '잠 15:16', '잠언 15장 16절', '가산이 적어도 여호와를 경외하는 것이 크게 부하고 번뇌하는 것보다 나으니라', null, false),
  (1135, 'psalm', 135, 3, '잠 15:17', '잠 15:17', '잠언 15장 17절', '채소를 먹으며 서로 사랑하는 것이 살진 소를 먹으며 서로 미워하는 것보다 나으니라', null, false),
  (1136, 'psalm', 136, 4, '잠 16:1', '잠 16:1', '잠언 16장 1절', '마음의 경영은 사람에게 있어도 말의 응답은 여호와께로부터 나오느니라', null, false),
  (1137, 'psalm', 137, 5, '잠 16:3', '잠 16:3', '잠언 16장 3절', '너의 행사를 여호와께 맡기라 그리하면 네가 경영하는 것이 이루어지리라', null, false),
  (1138, 'psalm', 138, 6, '잠 16:7', '잠 16:7', '잠언 16장 7절', '사람의 행위가 여호와를 기쁘시게 하면 그 사람의 원수라도 그와 더불어 화목하게 하시느니라', null, false),
  (1139, 'psalm', 139, 7, '잠 16:9', '잠 16:9', '잠언 16장 9절', '사람이 마음으로 자기의 길을 계획할지라도 그의 걸음을 인도하시는 이는 여호와시니라', null, false),
  (1140, 'psalm', 140, 8, '잠 16:18', '잠 16:18', '잠언 16장 18절', '교만은 패망의 선봉이요 거만한 마음은 넘어짐의 앞잡이니라', null, false),
  (1141, 'psalm', 141, 9, '잠 16:24', '잠 16:24', '잠언 16장 24절', '선한 말은 꿀송이 같아서 마음에 달고 뼈에 양약이 되느니라', null, false),
  (1142, 'psalm', 142, 10, '잠 16:32', '잠 16:32', '잠언 16장 32절', '노하기를 더디하는 자는 용사보다 낫고 자기의 마음을 다스리는 자는 성을 빼앗는 자보다 나으니라', null, false),
  (1143, 'psalm', 143, 11, '잠 17:1', '잠 17:1', '잠언 17장 1절', '마른 떡 한 조각만 있고도 화목하는 것이 제육이 집에 가득하고도 다투는 것보다 나으니라', null, false),
  (1144, 'psalm', 144, 12, '잠 17:3', '잠 17:3', '잠언 17장 3절', '도가니는 은을, 풀무는 금을 연단하거니와 여호와는 마음을 연단하시느니라', null, false),
  (1145, 'psalm', 145, 1, '잠 17:17', '잠 17:17', '잠언 17장 17절', '친구는 사랑이 끊어지지 아니하고 형제는 위급한 때를 위하여 났느니라', null, false),
  (1146, 'psalm', 146, 2, '잠 17:22', '잠 17:22', '잠언 17장 22절', '마음의 즐거움은 양약이라도 심령의 근심은 뼈를 마르게 하느니라', null, false),
  (1147, 'psalm', 147, 3, '잠 18:10', '잠 18:10', '잠언 18장 10절', '여호와의 이름은 견고한 망대라 의인은 그리로 달려가서 안전함을 얻느니라', null, false),
  (1148, 'psalm', 148, 4, '잠 18:21', '잠 18:21', '잠언 18장 21절', '죽고 사는 것이 혀의 힘에 달렸나니 혀를 쓰기 좋아하는 자는 혀의 열매를 먹으리라', null, false),
  (1149, 'psalm', 149, 5, '잠 19:11', '잠 19:11', '잠언 19장 11절', '노하기를 더디 하는 것이 사람의 슬기요 허물을 용서하는 것이 자기의 영광이니라', null, false),
  (1150, 'psalm', 150, 6, '잠 19:17', '잠 19:17', '잠언 19장 17절', '가난한 자를 불쌍히 여기는 것은 여호와께 꾸어 드리는 것이니 그의 선행을 그에게 갚아 주시리라', null, false),
  (1151, 'psalm', 151, 7, '잠 19:21', '잠 19:21', '잠언 19장 21절', '사람의 마음에는 많은 계획이 있어도 오직 여호와의 뜻만이 완전히 서리라', null, false),
  (1152, 'psalm', 152, 8, '잠 21:3', '잠 21:3', '잠언 21장 3절', '공의와 정의를 행하는 것은 제사 드리는 것보다 여호와께서 기쁘게 여기시느니라', null, false),
  (1153, 'psalm', 153, 9, '잠 21:31', '잠 21:31', '잠언 21장 31절', '싸울 날을 위하여 마병을 예비하거니와 이김은 여호와께 있느니라', null, false),
  (1154, 'psalm', 154, 10, '잠 22:1', '잠 22:1', '잠언 22장 1절', '많은 재물보다 명예를 택할 것이요 은이나 금보다 은총을 더욱 택할 것이니라', null, false),
  (1155, 'psalm', 155, 11, '잠 22:4', '잠 22:4', '잠언 22장 4절', '겸손과 여호와를 경외함의 보상은 재물과 영광과 생명이니라', null, false),
  (1156, 'psalm', 156, 12, '잠 22:6', '잠 22:6', '잠언 22장 6절', '마땅히 행할 길을 아이에게 가르치라 그리하면 늙어도 그것을 떠나지 아니하리라', null, false),
  (1157, 'psalm', 157, 1, '잠 24:16', '잠 24:16', '잠언 24장 16절', '대저 의인은 일곱 번 넘어질지라도 다시 일어나려니와 악인은 재앙으로 말미암아 엎드러지느니라', null, false),
  (1158, 'psalm', 158, 2, '잠 25:11', '잠 25:11', '잠언 25장 11절', '경우에 합당한 말은 아로새긴 은 쟁반에 금 사과니라', null, false),
  (1159, 'psalm', 159, 3, '잠 27:1', '잠 27:1', '잠언 27장 1절', '너는 내일 일을 자랑하지 말라 하루 동안에 무슨 일이 일어날는지 네가 알 수 없음이니라', null, false),
  (1160, 'psalm', 160, 4, '잠 27:2', '잠 27:2', '잠언 27장 2절', '타인이 너를 칭찬하게 하고 네 입으로는 하지 말며 외인이 너를 칭찬하게 하고 네 입술로는 하지 말지니라', null, false),
  (1161, 'psalm', 161, 5, '잠 27:17', '잠 27:17', '잠언 27장 17절', '철이 철을 날카롭게 하는 것 같이 사람이 그의 친구의 얼굴을 빛나게 하느니라', null, false),
  (1162, 'psalm', 162, 6, '잠 28:1', '잠 28:1', '잠언 28장 1절', '악인은 쫓아오는 자가 없어도 도망하나 의인은 사자 같이 담대하니라', null, false),
  (1163, 'psalm', 163, 7, '잠 28:13', '잠 28:13', '잠언 28장 13절', '자기의 죄를 숨기는 자는 형통하지 못하나 죄를 자복하고 버리는 자는 불쌍히 여김을 받으리라', null, false),
  (1164, 'psalm', 164, 8, '잠 29:18', '잠 29:18', '잠언 29장 18절', '묵시가 없으면 백성이 방자히 행하거니와 율법을 지키는 자는 복이 있느니라', null, false),
  (1165, 'psalm', 165, 9, '잠 29:25', '잠 29:25', '잠언 29장 25절', '사람을 두려워하면 올무에 걸리게 되거니와 여호와를 의지하는 자는 안전하리라', null, false),
  (1166, 'psalm', 166, 10, '잠 30:5', '잠 30:5', '잠언 30장 5절', '하나님의 말씀은 다 순전하며 하나님은 그를 의지하는 자의 방패시니라', null, false),
  (1167, 'psalm', 167, 11, '잠 31:10', '잠 31:10', '잠언 31장 10절', '누가 현숙한 여인을 찾아 얻겠느냐 그의 값은 진주보다 더 하니라', null, false),
  (1168, 'psalm', 168, 12, '잠 31:30', '잠 31:30', '잠언 31장 30절', '고운 것도 거짓되고 아름다운 것도 헛되나 오직 여호와를 경외하는 여자는 칭찬을 받을 것이라', null, false),
  (1169, 'psalm', 169, 1, '전 3:1', '전 3:1', '전도서 3장 1절', '범사에 기한이 있고 천하 만사가 다 때가 있나니', null, false),
  (1170, 'psalm', 170, 2, '전 4:6', '전 4:6', '전도서 4장 6절', '두 손에 가득하고 수고하며 바람을 잡는 것보다 한 손에만 가득하고 평온함이 더 나으니라', null, false),
  (1171, 'psalm', 171, 3, '전 4:9', '전 4:9', '전도서 4장 9절', '두 사람이 한 사람보다 나음은 그들이 수고함으로 좋은 상을 얻을 것임이라', null, false),
  (1172, 'psalm', 172, 4, '전 4:12', '전 4:12', '전도서 4장 12절', '한 사람이면 패하겠거니와 두 사람이면 맞설 수 있나니 세 겹 줄은 쉽게 끊어지지 아니하느니라', null, false),
  (1173, 'psalm', 173, 5, '전 5:10', '전 5:10', '전도서 5장 10절', '은을 사랑하는 자는 은으로 만족하지 못하고 풍요를 사랑하는 자는 소득으로 만족하지 아니하나니 이것도 헛되도다', null, false),
  (1174, 'psalm', 174, 6, '전 7:1', '전 7:1', '전도서 7장 1절', '좋은 이름이 좋은 기름보다 낫고 죽는 날이 출생하는 날보다 나으며', null, false),
  (1175, 'psalm', 175, 7, '전 7:8', '전 7:8', '전도서 7장 8절', '일의 끝이 시작보다 낫고 참는 마음이 교만한 마음보다 나으니', null, false),
  (1176, 'psalm', 176, 8, '전 9:10', '전 9:10', '전도서 9장 10절', '네 손이 일을 얻는 대로 힘을 다하여 할지어다 네가 장차 들어갈 스올에는 일도 없고 계획도 없고 지식도 없고 지혜도 없음이니라', null, false),
  (1177, 'psalm', 177, 9, '전 11:1', '전 11:1', '전도서 11장 1절', '너는 네 떡을 물 위에 던져라 여러 날 후에 도로 찾으리라', null, false),
  (1178, 'psalm', 178, 10, '전 12:1', '전 12:1', '전도서 12장 1절', '너는 청년의 때에 너의 창조주를 기억하라 곧 곤고한 날이 이르기 전에, 나는 아무 낙이 없다고 할 해들이 가깝기 전에', null, false),
  (1179, 'psalm', 179, 11, '전 12:13', '전 12:13', '전도서 12장 13절', '일의 결국을 다 들었으니 하나님을 경외하고 그의 명령들을 지킬지어다 이것이 모든 사람의 본분이니라', null, false),
  (1180, 'psalm', 180, 12, '전 12:14', '전 12:14', '전도서 12장 14절', '하나님은 모든 행위와 모든 은밀한 일을 선악 간에 심판하시리라', null, false)
